// HasKeuskupan applies the HasEdge predicate on the "keuskupan" edge.
func HasKeuskupan() predicate.Paroki {
	return predicate.Paroki(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, KeuskupanTable, KeuskupanColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasKeuskupanWith applies the HasEdge predicate on the "keuskupan" edge with a given conditions (other predicates).
func HasKeuskupanWith(preds ...predicate.Keuskupan) predicate.Paroki {
	return predicate.Paroki(func(s *sql.Selector) {
		step := newKeuskupanStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

